import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';

// Receipts are generated by the trusted local lead, never taken from an issue.
export function validateReportGate(p) {
  const fail = message => { throw Error('Automatic release blocked: '+message); };
  if (p?.schema !== 'oled-auto-release-v1' || p.repo !== 'bc1224/oled-night') fail('wrong project or receipt schema');
  if (!/^[a-f0-9]{40}$/.test(p.sha || '') || !/^[a-f0-9]{40}$/.test(p.base || '') || p.sha===p.base) fail('missing exact candidate and base');
  if (!Number.isSafeInteger(p.issue) || p.issue<1) fail('missing issue number');
  if (p.reproduction?.baseExit===0 || !Number.isSafeInteger(p.reproduction?.baseExit) || p.reproduction.baseExit<1 || p.reproduction?.fixedExit!==0) fail('old-source failure and fixed-source pass required');
  if (!/^[a-z][a-z-]+$/.test(p.fixture || '')) fail('missing public regression fixture');
  if (!Array.isArray(p.files) || !p.files.length || p.files.some(f => !/^(?:content\.js|color-utils\.js|youtube-theme\.js|settings\.js|manifest\.json|CHANGELOG\.md|tests\/(?:e2e|lab)\/[-a-zA-Z0-9_./]+|docs\/lab\/[-a-zA-Z0-9_./]+)$/.test(f) || f.includes('..') || f.includes('/baselines/'))) fail('change outside runtime bug and test scope');
  if (p.permissionsChanged !== false || p.dependenciesChanged !== false) fail('permissions/dependencies changed');
  if (p.review?.verdict !== 'accept' || p.review?.sha !== p.sha || p.review?.independent !== true || p.review?.profile !== 'review' || p.review?.model !== 'gpt-6-luna' || !/^[a-f0-9]{64}$/.test(p.review?.receiptHash || '')) fail('independent exact-source acceptance with authorized reviewer required');
  if (p.ci?.sha!==p.sha || p.ci?.conclusion!=='success' || !Number.isSafeInteger(p.ci?.runId) || p.ci.runId<1) fail('successful exact-source CI required');
  return true;
}

if (process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href) {
  const p=JSON.parse(readFileSync(process.argv[2], 'utf8'));
  validateReportGate(p);
  if (execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim()!==p.sha) throw Error('Receipt is not current HEAD');
  const files=execFileSync('git',['diff','--name-only',p.base,p.sha],{encoding:'utf8'}).trim().split('\n').filter(Boolean).sort();
  if (JSON.stringify(files)!==JSON.stringify([...p.files].sort())) throw Error('Changed-file receipt mismatch');
  const base=JSON.parse(execFileSync('git',['show',p.base+':manifest.json'],{encoding:'utf8'}));
  const manifest=JSON.parse(readFileSync('manifest.json','utf8'));
  const a={...base},b={...manifest}; delete a.version;delete b.version;
  if (JSON.stringify(a)!==JSON.stringify(b) || base.version===manifest.version) throw Error('Only an incremented manifest version is permitted');
  const v=version=>version.split('.').reduce((total,n)=>total*1000+Number(n),0);
  if (v(manifest.version)<=v(base.version)) throw Error('Version must increase');
  const review=JSON.parse(readFileSync(p.review.receiptPath,'utf8'));
  const digest=createHash('sha256').update(readFileSync(p.review.receiptPath)).digest('hex');
  if (digest!==p.review.receiptHash || review.verdict!=='accept') throw Error('Review artifact does not match acceptance');
  const run=JSON.parse(execFileSync('gh',['api','repos/bc1224/oled-night/actions/runs/'+p.ci.runId],{encoding:'utf8'}));
  if (run.head_sha!==p.sha || run.conclusion!=='success' || run.name!=='Tests' || run.head_branch!=='main' || run.event!=='push') throw Error('Provider CI receipt mismatch');
  const issue=JSON.parse(execFileSync('gh',['issue','view',String(p.issue),'--repo','bc1224/oled-night','--json','state,labels'],{encoding:'utf8'}));
  if (issue.state!=='OPEN' || !issue.labels.some(l=>l.name==='oled-report')) throw Error('Issue is not an open labelled report');
  const {cases}=await import('../tests/lab/catalog.mjs');
  if (!cases.some(c=>c.id===p.fixture)) throw Error('Fixture missing from public catalog');
  // Existing gate independently checks the retained exact-source lab artifact.
  execFileSync(process.execPath,['tools/verify-release-gate.mjs'],{stdio:'inherit',env:{...process.env,GITHUB_SHA:p.sha}});
  console.log('PASS automatic report release gate: '+p.sha);
}
